1	import type { BrowserApi, LoggerLike, Tab } from '../models'
2	import { TEMP_CONTAINERS_EXTENSION_IDS } from '../constants'
3	
4	export interface TcLayerDeps {
5		readonly browserApi: BrowserApi
6		readonly logger: LoggerLike
7	}
8	
9	export interface TcLayer {
10		readonly extensionId: string | null
11		/** 16-px icon URL for the TC extension itself, or null if TC is not installed. */
12		readonly iconUrl: string | null
13		isPresent(): boolean
14		initialize(): Promise<void>
15		isTempContainer(cookieStoreId: string): Promise<boolean>
16		createTempContainer(url: string, index: number, windowId: number): Promise<Tab>
17	}
18	
19	export class TcLayerImpl implements TcLayer {
20		private readonly browserApi: BrowserApi
21		private readonly logger: LoggerLike
22		private _extensionId: string | null = null
23		private _iconUrl: string | null = null
24	
25		constructor(deps: TcLayerDeps) {
26			this.browserApi = deps.browserApi
27			this.logger = deps.logger
28		}
29	
30		get extensionId(): string | null {
31			return this._extensionId
32		}
33	
34		get iconUrl(): string | null {
35			return this._iconUrl
36		}
37	
38		isPresent(): boolean {
39			return this._extensionId !== null
40		}
41	
42		async initialize(): Promise<void> {
43			for (const extensionId of TEMP_CONTAINERS_EXTENSION_IDS) {
44				try {
45					const extensionInfo = await this.browserApi.management.get(extensionId)
46					if (extensionInfo.enabled) {
47						this._extensionId = extensionId
48						const icon = extensionInfo.icons?.find(i => i.size === 16) ?? extensionInfo.icons?.[0]
49						this._iconUrl = icon?.url ?? null
50						this.debug('Temporary Containers detected:', extensionInfo.name, extensionId)
51						return
52					}
53				} catch {
54					// Extension not installed — try next
55				}
56			}
57			this._extensionId = null
58			this.debug('No Temporary Containers extension found')
59		}
60	
61		async isTempContainer(cookieStoreId: string): Promise<boolean> {
62			if (!this._extensionId) return false
63			try {
64				return await this.browserApi.runtime.sendMessage(
65					this._extensionId,
66					{ method: 'isTempContainer', cookieStoreId },
67				) as boolean
68			} catch {
69				return false
70			}
71		}
72	
73		async createTempContainer(url: string, index: number, windowId: number): Promise<Tab> {
74			if (!this._extensionId) throw new Error('No Temporary Containers extension detected')
75			const tab = await this.browserApi.runtime.sendMessage(this._extensionId, {
76				method: 'createTabInTempContainer',
77				url,
78				active: true,
79			})
80			return tab as Tab
81		}
82	
83		private debug(...args: unknown[]): void {
84			this.logger.log(...args)
85		}
86	}
