9	export interface CloneRuntime {
10		cloneToContainer(sourceTab: Tab, targetCookieStoreId: string): Promise<void>
11		cloneToTemporary(sourceTab: Tab): Promise<void>
12	}
13	
14	function cookieToSetDetails(cookie: Cookie, storeId: string): CookieSetDetails {
15		const domain = cookie.domain.replace(/^\./, '')
16		const url = `${cookie.secure ? 'https' : 'http'}://${domain}${cookie.path}`
17	
18		const details: CookieSetDetails = {
19			url,
20			name: cookie.name,
21			value: cookie.value,
22			domain: cookie.domain,
23			path: cookie.path,
24			secure: cookie.secure,
25			httpOnly: cookie.httpOnly,
26			sameSite: cookie.sameSite,
27			storeId,
28		}
29	
30		if (cookie.expirationDate !== undefined) {
31			details.expirationDate = cookie.expirationDate
32		}
33	
34		return details
35	}
36	
37	export class CloneRuntimeImpl implements CloneRuntime {
38		constructor(private readonly deps: CloneRuntimeDeps) {}
39	
40		async cloneToContainer(sourceTab: Tab, targetCookieStoreId: string): Promise<void> {
41			const { browserApi } = this.deps
42	
43			await this.copyCookies(sourceTab, targetCookieStoreId)
44	
45			const newTab = await browserApi.tabs.create({
46				cookieStoreId: targetCookieStoreId,
47				url: sourceTab.url ?? '',
48				index: sourceTab.index + 1,
49			})
50	
51			this.registerDiscardOnComplete(sourceTab, newTab)
52		}
53	
54		async cloneToTemporary(sourceTab: Tab): Promise<void> {
55			const { tcLayer } = this.deps
56	
57			const newTab = await tcLayer.createTempContainer(
58				sourceTab.url ?? '',
59				sourceTab.index + 1,
60				sourceTab.windowId ?? 0,
61			)
62	
63			await this.copyCookies(sourceTab, newTab.cookieStoreId ?? '')
64			this.registerDiscardOnComplete(sourceTab, newTab)
65		}
66	
67		private async copyCookies(sourceTab: Tab, targetCookieStoreId: string): Promise<void> {
68			const { browserApi } = this.deps
69	
70			const cookies = await browserApi.cookies.getAll({ storeId: sourceTab.cookieStoreId ?? '' })
71			for (const cookie of cookies) {
72				await browserApi.cookies.set(cookieToSetDetails(cookie, targetCookieStoreId))
73			}
74		}
75	
76		private registerDiscardOnComplete(sourceTab: Tab, newTab: Tab): void {
77			const { browserApi } = this.deps
78	
79			browserApi.tabs.onUpdated.addListener(async (id, changeInfo) => {
80				if (id === newTab.id && changeInfo.status === 'complete') {
81					await browserApi.tabs.discard(sourceTab.id as number)
82				}
83			})
84		}
85	}
