48			this.browserApi.menus.onHidden.addListener(() => {
49				this.menuHandler.handleHidden()
50			})
51	
52			// Register menus.onClicked
53			this.browserApi.menus.onClicked.addListener(async (info, tab) => {
54				if (!tab) return
55				await this.menuHandler.handleClick(info, tab)
56			})
57	
58			// Register tabs.onUpdated for F4 isolation info
59			this.browserApi.tabs.onUpdated.addListener(async (id, changeInfo, tab) => {
60				await this.handleTabUpdated(id, changeInfo, tab)
61			})
62		}
63	
64		private async getPermanentContainers(): Promise<ContextualIdentity[]> {
65			const allContainers = await this.browserApi.contextualIdentities.query({})
66			const permanentContainers: ContextualIdentity[] = []
67			for (const c of allContainers) {
68				const isTemp = await this.tcLayer.isTempContainer(c.cookieStoreId)
69				if (!isTemp) permanentContainers.push(c)
70			}
71			return permanentContainers
72		}
